import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第48章 四十七天","description":"","frontmatter":{},"headers":[],"relativePath":"第48章_四十七天.md","filePath":"第48章_四十七天.md"}'),o={name:"第48章_四十七天.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第48章-四十七天" tabindex="-1">第48章 四十七天 <a class="header-anchor" href="#第48章-四十七天" aria-label="Permalink to &quot;第48章 四十七天&quot;">​</a></h1><p>从十二月十六号到一月底，她一句话没有。</p><p>那四十七天是我这一生里数得最清楚的四十七天。</p><p>头三天我还能忍。</p><p>第四条我开始把手机放在离我一米的地方，让它朝上。</p><p>第五条我把那个号从置顶的位置挪到最上面第二格，因为我怕第一格太明显。</p><p>第六条我把它挪回第一格。</p><p>那天晚上我在被子里想她的第七条规矩。</p><p>她写的是：要是我连续二十天没上线，你别去找我。</p><p>所以到第二十天之前，我什么都不用做。</p><p>第二十天那天，我在自习室里把笔放下，出去走了一圈。</p><p>冬天的操场只有我们这一届在跑，音乐一直放那两首歌。我在跑道上走了一圈半，鞋底下有薄薄的冰，踩下去咔嚓一声。</p><p>第二十天她没来。</p><p>我按规矩，没有找。</p><p>第二十五天，我们班有个男生家里出了事，我们几个人去他家帮忙搬东西。搬完我在他们家门口站着等车。</p><p>那一站就是四十分钟。</p><p>车来了我不上，因为那趟车会经过她家那边那条路。</p><p>我那时候没有想别的。我就是想从那条路上过一遍。</p><p>后来我还是上了。</p><p>车上我从窗户里往外看，看了一路。那条路我其实不知道具体是哪一段，我让她给我描述过：一个超市，一个银行，一个卖奶茶的，奶茶店旁边有一棵很歪的树。</p><p>我在车上看见了超市，看见了银行。</p><p>奶茶店没开门。</p><p>第三十天，我做了一件事。</p><p>我把手机里跟她有关的东西导出来一份。</p><p>那是我第一次干这个。我那时候不是为了留，是为了确定我没有在瞎想。我把那个号上的对话一条一条往前翻，翻到最早那一句&quot;我只有几分钟&quot;，再往前就什么都没有了。</p><p>因为那之前是旧号。</p><p>旧号上我们两年的东西，我不在里面。</p><p>我看着那个空白的地方，第一次明白她那句&quot;我在那个号上说的话不是我的&quot;是什么意思。</p><p>一个人两年的话可以被整个换掉。</p><p>第三十五天，我妈在饭桌上问我，那个同学还联系你吗。</p><p>我说，联系。</p><p>她说，人家小姑娘现在在干什么。</p><p>我说，在办出国。</p><p>她愣了一下，说你认识人家家里的事？</p><p>我说，听她说过一点。</p><p>我妈把筷子放下来，很认真地问我，你们俩是什么关系。</p><p>我说，同学。</p><p>我妈说，同学你会记这么清楚。</p><p>我那时候没答。</p><p>我妈也没再问。她把最后一块鱼夹到我碗里，说吃你的饭。</p><p>那顿饭后我一个人洗了碗。我洗了很久，水一直开着，手都泡白了。</p><p>我不是在想我妈那一句。</p><p>我在想：如果她哪天回来，第一句会说什么。</p><p>第四十天，她那个号上出现了一条动态。</p><p>她以前不发东西。她在那个号上只发过一次，是三月，一张很糊的图，配了两个字。</p><p>那一次是一条转发，转发的是一个卖家挂出来的东西，一句话都没说。</p><p>我点进去看了半天，才看明白那是一批被坑的团购，她在替一帮人讨说法。</p><p>也就是说，她第四十天还在做别的事。</p><p>她没有出事。</p><p>我知道这个以后，那天晚上睡得特别好。</p><p>第三十八天那天，我犯了一个很丢人的错。</p><p>我把日子数错了。</p><p>我从十二月十六号往上加，加到一月底，我算成了四月，又算成二月。</p><p>我在纸上重新列了一遍，算出那天是第四十一天。</p><p>我拿手机看日历，才发现是第三十八天。</p><p>那天晚上我坐在床上很久。</p><p>因为我意识到我不是在数日子，我是在找一个能动手的边界。</p><p>她写的第七条是二十天。我把它推到了四十天。</p><p>再过几天，我就会推到一个我自己可以说服自己的地方。</p><p>到那时候我就可以名正言顺地去找她。</p><p>我想明白这一层，心里发凉。</p><p>人把自己拖过规矩的时候，是不需要理由的，只需要算术。</p><p>那天晚上我在本子上写了一行。</p><p>我写：我今天把她写的规矩自己改了三天。</p><p>写完我把那一页折了一角。</p><p>第四十三天，沈聿在走廊上拦住了我。</p><p>他说，你最近不对劲。</p><p>我说，没有。</p><p>他说，你等谁呢。</p><p>我说，等成绩。</p><p>他说，你成绩挺好的。</p><p>我说，那还有别的。</p><p>他看了我一会儿。</p><p>他说，你别把自己熬成那样。</p><p>他说，人要是想找你，她总会找到你。</p><p>他说，她要是不找，你等到四十岁也没用。</p><p>我说，她不是不找。</p><p>他说，那是什么。</p><p>我说，她那边说话要挑地方。</p><p>沈聿不说话了。</p><p>过了一会儿他问了一句，那我问你，她知道你在等吗。</p><p>我说，她知道。</p><p>他说，你跟她说过你在等？</p><p>我说，没有。</p><p>他看着我。</p><p>他说，那她怎么知道。</p><p>那天夜里我想了很久这一句。</p><p>这是我第一次正面撞到我和她之间最要命的那个东西。</p><p>我不说。</p><p>她也不知道。</p><p>她只看到我照做。</p><p>而规矩是我俩一起定的，第七条是她写的。她写下那一条的时候，其实也知道自己以后要拿它挡我。</p><p>第四十七天，一月底。</p><p>那天下午我在宿舍收拾东西，准备回家。我把那个搪瓷杯洗了，把本子从抽屉里拿出来。</p><p>本子已经很厚了。</p><p>我把它塞进包的时候，手机亮了一下。</p><p>我拿起来看。</p><p>她说：你还在吗。</p><p>后面跟着一个哭的表情。</p><p>我拿着手机坐在床沿上，没有立刻回。</p><p>我先把本子放回桌上，把它摊平，又拿起来。</p><p>后来我回了两个字。</p><p>我说，在。</p><p>她隔了三秒回。</p><p>三秒。</p><p>四十七天，她用三秒回。</p><p>她说，那我可以说两句了。</p><p>她说，你先别高兴，我不是回来了，我是来问你要一个地址。</p><p>她说，我被坑了一批谷子，我要挂在你那边收，你帮我发。</p><p>她说，放心，不让你白干。</p><p>我看着那三行字，笑了一下。</p><p>笑完我发现我眼睛有点热。</p><p>四十七天以后，她回来的第一句话不是道歉，不是解释，是让我帮她发货。</p><p>我那时候觉得这很正常。</p><p>很多年以后我才知道，那不是正常。</p><p>那是她唯一会的方式：不说我想你了，说我有件事要麻烦你。</p>',116)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
